OUT=Path(__file__).resolve().parent;OLD=Path('/workspace/scratch/500ec816102b/model-repo/build/complex-nonlinear-20261024/thermoplastic/notched_connector_transient_hardening_v4') # Keep the declared original physical control explicit.
def read(folder): # Load only full physical fields, geometry and controls needed by this independent diagnostic.
    with np.load(folder/'fields.npz') as z:a={k:z[k] for k in ['fe_xyz','tet','controls']};a['states']=z['states'][:,:,:17].copy() # Preserve nodalU/T, all6stress,PEEQ and all6plastic-metric components.
    return a,json.loads((folder/'receipt.json').read_text()) # Keep native quality gates attached to the actual fields.
def relative(a,b,w): # Use the same physical volume-weighted trajectory norm as the original mesh gate.
    return float(np.sqrt(np.einsum('p,tp->',w,np.sum((a-b)**2,axis=-1))/max(np.einsum('p,tp->',w,np.sum(b*b,axis=-1)),1.e-30))) # Do not average component-relative errors or remove high-error stations.
def jumps(a): # Measure numerical pressure discontinuity across every shared internal tetrahedral face.
    tet=a['tet'];xyz=a['fe_xyz'];n=len(xyz);pressure=a['states'][:,n:,4:7].mean(axis=-1).reshape(len(a['controls']),len(tet),4);B=np.full((4,4),.138196601125011);np.fill_diagonal(B,.585410196624968);corner=np.einsum('ij,tej->tei',np.linalg.inv(B),pressure);faces={} # Reconstruct the native local linear pressure from all four actual quadrature values.
    for el,nodes in enumerate(tet[:,:4]): # Pair conforming real mesh faces without distance-based smoothing.
        for opposite in range(4): # A tetrahedron has exactly four triangular faces.
            local=tuple(i for i in range(4) if i!=opposite);key=tuple(sorted(int(nodes[i]) for i in local));faces.setdefault(key,[]).append((el,local)) # Preserve the native incident elements and corner ordering.
    pairs=[(key,values) for key,values in faces.items() if len(values)==2];area=[];left=[];right=[] # Exclude external boundaries from this internal continuity diagnostic only.
    for key,values in pairs: # Use the same physical face centroid from both adjacent element pressure polynomials.
        points=xyz[list(key)];area.append(np.linalg.norm(np.cross(points[1]-points[0],points[2]-points[0]))/2.);left.append(corner[:,values[0][0],list(values[0][1])].mean(axis=1));right.append(corner[:,values[1][0],list(values[1][1])].mean(axis=1)) # Integrate actual internal face area rather than counting elements equally.
    l=np.asarray(left).T;r=np.asarray(right).T;w=np.asarray(area);den=np.einsum('p,tp->',w,(l*l+r*r)/2.);return {'internal_faces':len(pairs),'area_weighted_pressure_jump_relative':float(np.sqrt(np.einsum('p,tp->',w,(l-r)**2)/max(den,1.e-30))),'scope':'Diagnostic only: discontinuous FE stress recovery need not be exactly continuous, and this metric never replaces native equilibrium or the frozen whole-field mesh gate.'} # Disclose the limits of the checkerboard indicator.
def run(): # Analyze the exact completed same-geometry A/B pair without declaring reference convergence.
    new=OUT/'cases/tv2_c3d10t_mesh07';old=OLD/'cases/th4_000';a,ra=read(old);b,rb=read(new);assert np.array_equal(a['fe_xyz'],b['fe_xyz']) and np.array_equal(a['tet'],b['tet']) and np.array_equal(a['controls'],b['controls']);n=len(a['fe_xyz']);x=a['states'];y=b['states'];corners=a['fe_xyz'][a['tet'][:,:4]];w=np.repeat(abs(np.linalg.det(corners[:,1:]-corners[:,0,None]))/24.,4);sx=x[:,n:,4:10];sy=y[:,n:,4:10];px=sx[:,:,:3].mean(axis=-1);py=sy[:,:,:3].mean(axis=-1);dx=sx.copy();dy=sy.copy();dx[:,:,:3]-=px[:,:,None];dy[:,:,:3]-=py[:,:,None] # Compare every native location on identical geometry and times.
    result={'status':'CONTROLLED_AB_DIAGNOSTIC_NOT_MESH_QUALIFICATION','old_native_quality':ra['quality'],'new_native_quality':rb['quality'],'temperature_fields_exactly_identical':bool(np.array_equal(x[:,:n,3],y[:,:n,3])),'temperature_max_abs_difference':float(abs(x[:,:n,3]-y[:,:n,3]).max()),'stress_ab_relative':relative(sx,sy,w),'hydrostatic_ab_relative':relative(px[:,:,None],py[:,:,None],w),'deviatoric_ab_relative':relative(dx,dy,w),'peeq_ab_relative':relative(x[:,n:,10:11],y[:,n:,10:11],w),'old_pressure_jump':jumps(a),'new_pressure_jump':jumps(b),'old_maximum_peeq':ra.get('maximum_peeq'),'new_maximum_peeq':rb.get('maximum_peeq'),'new_independent_physics':rb.get('independent_physics'),'required_next_gate':'Same C3D10T version spatial and temporal refinement under unchanged5percent fullstress/PEEQ thresholds; originalC3D10v4 remainsHOLD.'} # Avoid treating a change between numerical formulations as a convergence proof.
